#!/usr/bin/env bash
# SC-6611: offline check of the VAP synapse-reloj-jobs (platform/reloj/vap-jobs.yaml) with the Kyverno
# CLI (v1.18.x, the cluster's). The CLI does not resolve a binding's paramRef, so the harness renders a
# copy of the VAP whose `d` variable is a CEL map literal of params.yaml (the shape of
# synapse/synapse-reloj-plantillas, generated by synapse:scripts/reloj/plantillas.py): every validation
# is the real one, only the parameter plumbing is replaced (that part is proven live with
# `kubectl create --dry-run=server --as=system:serviceaccount:synapse:synapse-adapter-k8s`).
# Jobs are built as synapse-adapter-k8s builds them; first line `# user: <username>` is the requester.
# deny-* => the VAP fails; allow-* => it passes.   usage: ./run-offline.sh [path-to-kyverno-binary]
set -u
DIR="$(cd "$(dirname "$0")" && pwd)"
K="${1:-kyverno}"
TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
python3 - "$DIR/../../platform/reloj/vap-jobs.yaml" "$DIR/params.yaml" "$TMP/vap.yaml" <<'PY'
import json, sys, yaml
docs = [d for d in yaml.safe_load_all(open(sys.argv[1])) if d]
vap = next(d for d in docs if d["kind"] == "ValidatingAdmissionPolicy")
data = yaml.safe_load(open(sys.argv[2]))["data"]
literal = "{" + ", ".join(f"{json.dumps(k)}: {json.dumps(v)}" for k, v in sorted(data.items())) + "}"
vap["spec"].pop("paramKind", None)
for v in vap["spec"]["variables"]:
    if v["name"] == "d":
        v["expression"] = literal
deny = next(d for d in docs if d["kind"] == "ValidatingAdmissionPolicyBinding" and d["metadata"]["name"].endswith("-deny"))
deny["spec"].pop("paramRef", None)
deny["spec"]["matchResources"] = {}  # every namespace: the namespace rule is a validation of its own
yaml.safe_dump_all([vap, deny], open(sys.argv[3], "w"))
PY
bad=0
for f in "$DIR"/deny-*.yaml "$DIR"/allow-*.yaml; do
  name="$(basename "$f" .yaml)"
  user="$(sed -n '1s/^# user: //p' "$f")"
  printf 'apiVersion: cli.kyverno.io/v1alpha1\nkind: UserInfo\nmetadata:\n  name: u\nuserInfo:\n  username: "%s"\n' "$user" > "$TMP/user.yaml"
  out="$("$K" apply "$TMP/vap.yaml" --resource "$f" --userinfo "$TMP/user.yaml" --detailed-results 2>&1)"
  summary="$(printf '%s\n' "$out" | grep -E 'pass:.*fail:' | tail -1)"
  fails="$(printf '%s' "$summary" | sed -E 's/.*fail: ([0-9]+).*/\1/')"
  why="$(printf '%s\n' "$out" | grep -E '^1 - ' | head -1 | cut -c1-140)"
  case "$name" in
    deny-*)  [ "${fails:-0}" = "1" ] && echo "PASS  $name  [$why]" || { echo "FAIL  $name  ($summary)"; bad=$((bad+1)); };;
    allow-*) [ "$fails" = "0" ] && echo "PASS  $name  ($summary)" || { echo "FAIL  $name  ($summary) $why"; bad=$((bad+1)); };;
  esac
done
echo "failures: $bad"
exit $((bad > 0))
